<script setup lang="ts">
import {ref,watch} from 'vue'
import {NButton,NInput,NForm,NFormItem,NSpace,NAlert,useMessage} from 'naive-ui'
import {Download,Link,Server,KeyRound,Settings2} from '@lucide/vue'
import {state,api,refresh,logout,download} from '../store'
import {bytes,protocolNames} from '../domain'
const emit=defineEmits(['setup']);const message=useMessage(),domain=ref(state.data.entry_domain||''),checkedDomain=ref(''),checking=ref(false),domainBusy=ref(false),result=ref(''),password=ref(''),passwordBusy=ref(false)
watch(domain,()=>{checkedDomain.value='';result.value=''})
async function check(){checking.value=true;try{const v=await api('/api/domain/check',{domain:domain.value.trim()});checkedDomain.value=v.ready?domain.value.trim():'';result.value=v.ready?'解析正确，可以启用域名入口。':'解析尚未就绪，请将 A 记录仅解析到 '+v.expected}catch(e){message.error((e as Error).message)}finally{checking.value=false}}
async function activate(){if(!checkedDomain.value||checkedDomain.value!==domain.value.trim())return;domainBusy.value=true;try{await api('/api/domain/activate',{domain:checkedDomain.value});await refresh();message.success('已启用域名入口')}catch(e){message.error((e as Error).message)}finally{domainBusy.value=false}}
async function changePassword(){passwordBusy.value=true;try{await api('/api/password',{password:password.value});password.value='';await logout().catch(()=>{});message.success('密码已修改，请重新登录')}catch(e){message.error((e as Error).message)}finally{passwordBusy.value=false}}
// Download through the authenticated browser cookie, without exposing any server credentials.
function installer(){location.href='/api/installer'}
const command='curl -fsSL https://raw.githubusercontent.com/lkyoh/relay-console/main/relay-panel-install.sh -o /tmp/relay-panel-install.sh && sudo bash /tmp/relay-panel-install.sh --domain 你的域名'
</script>
<template><div class="page-heading"><div><div class="eyebrow">PREFERENCES</div><h1>系统设置</h1><p>管理入口、运行状态与独立安装</p></div></div><div class="settings-grid"><article class="panel settings-card span-2"><div class="section-heading plain"><div><h2><Settings2 :size="18"/>安装与初始化</h2><p class="muted">新服务器独立安装，首次登录通过向导完成配置。</p></div><NSpace><NButton @click="emit('setup')">查看初始化配置</NButton><NButton type="primary" @click="installer"><template #icon><Download :size="16"/></template>下载安装脚本</NButton></NSpace></div><div class="install-steps"><div><b>01</b><span>安装面板<small>Debian / Ubuntu · amd64 / arm64</small></span></div><div><b>02</b><span>网页初始化<small>管理员、域名与协议</small></span></div><div><b>03</b><span>导入落地<small>批量生成节点与订阅</small></span></div></div><details class="install-details"><summary>在线安装命令</summary><pre>{{command}}</pre><p class="muted">域名先解析到新服务器，选择仅 DNS。迁移旧链接使用服务器管理中的备用同步。</p></details></article>
<article class="panel settings-card"><h2><Link :size="18"/>固定域名入口</h2><NFormItem label="入口域名"><NInput v-model:value="domain" placeholder="relay.example.com"/></NFormItem><div class="dns-record"><span>A</span><b>{{domain||'你的域名'}}</b><span>→</span><code>{{state.data.server_ip}}</code></div><NSpace><NButton :loading="checking" @click="check">检查解析</NButton><NButton type="primary" :loading="domainBusy" :disabled="!checkedDomain" @click="activate">启用域名入口</NButton></NSpace><NAlert v-if="result" type="info" :show-icon="false" class="form-note">{{result}}</NAlert><dl><div><dt>当前节点地址</dt><dd>{{state.data.public_host}}</dd></div></dl></article>
<article class="panel settings-card"><h2><Server :size="18"/>服务器状态</h2><dl><div><dt>服务器</dt><dd>{{state.data.server_ip}}</dd></div><div><dt>代理服务</dt><dd><span class="status-dot" :class="{bad:!state.data.active}"/>{{state.data.active?'正常运行':'异常'}}</dd></div><div><dt>系统负载 · 1 分钟</dt><dd>{{state.traffic.system?.load?.toFixed(2)??'—'}}</dd></div><div><dt>内存</dt><dd>{{bytes(state.traffic.system?.memory_used)}} / {{bytes(state.traffic.system?.memory_total)}}</dd></div><div><dt>系统运行时间</dt><dd>{{Math.floor((state.traffic.system?.uptime||0)/86400)}} 天 {{Math.floor((state.traffic.system?.uptime||0)%86400/3600)}} 小时</dd></div></dl></article>
<article class="panel settings-card"><h2><KeyRound :size="18"/>管理密码</h2><NForm @submit.prevent="changePassword"><NFormItem label="新密码"><NInput v-model:value="password" type="password" autocomplete="new-password" placeholder="14～200 位"/></NFormItem><NButton attr-type="submit" :loading="passwordBusy" :disabled="password.length<14||password.length>200">修改密码并重新登录</NButton></NForm></article>
<article class="panel settings-card"><h2>节点与订阅</h2><dl><div><dt>可用协议</dt><dd>{{state.data.protocols.map(p=>protocolNames[p]).join(' / ')}}</dd></div><div><dt>流量统计</dt><dd>每条线路全部协议入口流量</dd></div><div><dt>更换落地</dt><dd>保留节点端口与认证身份</dd></div></dl></article></div></template>
